exercises.solution:
from urllib.parse import urlparse

def domaine_reel(lien):
    hote = urlparse(lien).hostname
    return ".".join(hote.split(".")[-2:])

def est_sosie(domaine, officiel):
    normal = domaine.replace("0", "o").replace("1", "l").replace("rn", "m")
    return domaine != officiel and normal == officiel

def signaux_trouves(message, signaux):
    texte = message.lower()
    return [s for s in signaux if s in texte]

from urllib.parse import urlparse

def domaine_reel(lien):
    hote = urlparse(lien).hostname
    return ".".join(hote.split(".")[-2:])

SIGNAUX = ["urgent", "bloqué", "code secret", "gagné", "cliquez"]

def verdict(message, lien, officiel):
    texte = message.lower()
    score = len([s for s in SIGNAUX if s in texte])
    if domaine_reel(lien) != officiel:
        score += 2
    if score == 0:
        return "fiable"
    if score <= 2:
        return "suspect"
    return "dangereux"
